mapper.select:
SELECT  FROM sys_print_binding
WHERE tenant_id = #{tenantId} AND application_id = #{applicationId}
  AND source_key = #{sourceKey} AND template_id = #{templateId} AND scene = #{scene} AND del_flag = 0

mapper.update:
UPDATE sys_print_binding SET is_default = #{row.isDefault}, sort_order = #{row.sortOrder},
    status = #{row.status}, binding_revision = binding_revision + 1,
    update_by = #{row.updateBy}, update_time = NOW()
WHERE tenant_id = #{row.tenantId} AND application_id = #{row.applicationId} AND id = #{row.id}
  AND source_key = #{row.sourceKey} AND scene = #{row.scene} AND template_id = #{row.templateId}
  AND del_flag = 0 AND binding_revision = #{expectedRevision} AND #{row.status} IN (0, 1)

UPDATE sys_print_binding SET del_flag = id, binding_revision = binding_revision + 1,
    update_by = #{actor}, update_time = NOW()
WHERE tenant_id = #{tenantId} AND id = #{id} AND del_flag = 0 AND binding_revision = #{expectedRevision}
